/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    dictclass flightclass = new dictclass(classNum(Flight));
    List flightList = flightClass.extendedBy();
    ListEnumerator enum = flightList.getEnumerator();
    container enabledFlights;


    while (enum.moveNext())
    {
        SysDictClass currentFlightClass = new SysDictClass(enum.current());
        Flight currentFlight = currentFlightClass.makeObject() as Flight;
        if (currentFlight != null)
        {
            enabledFlights += [currentFlightClass.name(), currentFlight.isEnabled()];
        }
    }
    info(con2Str(enabledFlights));        

}
